#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAXH 30
#define MAXW 30
#define MAXN 900
#define INF 1e18

typedef struct {
    int r, c;
} Cell;

int H, W;
char grid[MAXH][MAXW+1];
int id[MAXH][MAXW];
int N;
Cell cells[MAXN];
int start_id, goal_id;
int spring_ids[MAXN], spring_cnt;

double dist[MAXN][MAXN];
double dp[MAXN];
int visited[MAXN];

int dr[4] = {-1, 1, 0, 0};
int dc[4] = {0, 0, -1, 1};

int is_floor(char ch) {
    return ch == '.' || ch == 's' || ch == 'g';
}

void bfs(int src) {
    for (int i = 0; i < N; i++) dist[src][i] = INF;
    dist[src][src] = 0;
    int q[MAXN], front = 0, rear = 0;
    q[rear++] = src;
    while (front < rear) {
        int u = q[front++];
        int r = cells[u].r, c = cells[u].c;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (grid[nr][nc] == '#') continue;
            int v = id[nr][nc];
            if (v == -1) continue;
            if (dist[src][u] + 1 < dist[src][v]) {
                dist[src][v] = dist[src][u] + 1;
                q[rear++] = v;
            }
        }
    }
}

double solve() {
    // Build graph
    N = 0;
    spring_cnt = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#') {
                id[i][j] = -1;
                continue;
            }
            id[i][j] = N;
            cells[N].r = i;
            cells[N].c = j;
            if (grid[i][j] == 's') start_id = N;
            if (grid[i][j] == 'g') goal_id = N;
            if (grid[i][j] == '*') spring_ids[spring_cnt++] = N;
            N++;
        }
    }

    // BFS from every node
    for (int i = 0; i < N; i++) {
        bfs(i);
    }

    // Count floor tiles (excluding springs and stairs)
    int floor_cnt = 0;
    for (int i = 0; i < N; i++) {
        char ch = grid[cells[i].r][cells[i].c];
        if (ch == '.' || ch == 's') floor_cnt++;
    }

    // dp[i] = expected moves from node i to goal
    // Initialize with INF
    for (int i = 0; i < N; i++) dp[i] = INF;
    dp[goal_id] = 0;

    // Since graph is small, we can use value iteration / Bellman-Ford like approach
    // Because there are no negative cycles, we can iterate until convergence
    for (int iter = 0; iter < N * 5; iter++) {
        int changed = 0;
        for (int u = 0; u < N; u++) {
            if (u == goal_id) continue;
            char ch = grid[cells[u].r][cells[u].c];
            if (ch == '*') {
                // Spring: expected = 1 + average over all floor tiles of dp[floor]
                double sum = 0;
                for (int i = 0; i < N; i++) {
                    char ch2 = grid[cells[i].r][cells[i].c];
                    if (ch2 == '.' || ch2 == 's') {
                        sum += dp[i];
                    }
                }
                double val = 1.0 + sum / floor_cnt;
                if (val < dp[u] - 1e-12) {
                    dp[u] = val;
                    changed = 1;
                }
            } else {
                // Normal tile: can move to neighbors
                double best = INF;
                int r = cells[u].r, c = cells[u].c;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    if (grid[nr][nc] == '#') continue;
                    int v = id[nr][nc];
                    if (v == -1) continue;
                    double cand = 1.0 + dp[v];
                    if (cand < best) best = cand;
                }
                if (best < dp[u] - 1e-12) {
                    dp[u] = best;
                    changed = 1;
                }
            }
        }
        if (!changed) break;
    }

    return dp[start_id];
}

int main() {
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }
    double ans = solve();
    printf("%.10f\n", ans);
    return 0;
}

