#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAXR 105
#define MAXC 105
#define INF 1e100
#define EPS 1e-12

typedef struct {
    int r, c;
} Pos;

static char grid[MAXR][MAXC + 5];
static int id[MAXR][MAXC];
static int is_floor[MAXR][MAXC];
static int is_spring[MAXR][MAXC];
static int is_goal[MAXR][MAXC];
static int is_start[MAXR][MAXC];

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    memset(id, -1, sizeof(id));

    Pos *states = (Pos *)malloc(sizeof(Pos) * H * W);
    int n = 0;
    int sr = -1, sc = -1;

    long long floor_count = 0; /* tiles that springs can send to: '.' and 's' */

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char ch = grid[i][j];
            if (ch != '#') {
                id[i][j] = n;
                states[n].r = i;
                states[n].c = j;
                n++;
            }
            if (ch == '.' || ch == 's') floor_count++;
            if (ch == '*') is_spring[i][j] = 1;
            if (ch == 'g') is_goal[i][j] = 1;
            if (ch == 's') {
                is_start[i][j] = 1;
                sr = i; sc = j;
            }
        }
    }

    if (sr == -1) {
        free(states);
        return 0;
    }

    /* If there are no valid landing floor tiles for springs, then stepping on a spring
       can never be part of an optimal path unless unnecessary. The formula below would
       divide by zero, so handle separately by treating spring moves as impossible. */
    int spring_usable = (floor_count > 0);

    double *dp = (double *)malloc(sizeof(double) * n);
    double *ndp = (double *)malloc(sizeof(double) * n);

    for (int i = 0; i < n; i++) dp[i] = 0.0;

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    /* Value iteration on Bellman equations.
       Let F be average expected value over all landing floor tiles ('.' and 's').
       For each non-goal state x:
         E[x] = min over valid adjacent moves:
                1 + E[next]                  if next is normal floor/start
                1                            if next is goal
                1 + F                        if next is spring
       and F = average of E over landing floor tiles.
    */
    for (int iter = 0; iter < 200000; iter++) {
        double F = 0.0;
        if (spring_usable) {
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == '.' || grid[i][j] == 's') {
                        F += dp[id[i][j]];
                    }
                }
            }
            F /= (double)floor_count;
        }

        double maxdiff = 0.0;

        for (int k = 0; k < n; k++) {
            int r = states[k].r;
            int c = states[k].c;
            char ch = grid[r][c];

            if (ch == 'g') {
                ndp[k] = 0.0;
                continue;
            }

            double best = INF;

            for (int z = 0; z < 4; z++) {
                int nr = r + dr[z], nc = c + dc[z];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                char nch = grid[nr][nc];
                if (nch == '#') continue;

                double cand;
                if (nch == 'g') cand = 1.0;
                else if (nch == '*') {
                    if (!spring_usable) continue;
                    cand = 1.0 + F;
                } else {
                    cand = 1.0 + dp[id[nr][nc]];
                }

                if (cand < best) best = cand;
            }

            ndp[k] = best;
            double diff = fabs(ndp[k] - dp[k]);
            if (diff > maxdiff) maxdiff = diff;
        }

        for (int i = 0; i < n; i++) dp[i] = ndp[i];
        if (maxdiff < 1e-11) break;
    }

    int sid = id[sr][sc];
    printf("%.10f\n", dp[sid]);

    free(states);
    free(dp);
    free(ndp);
    return 0;
}

