int main() {
    int H, W;
    while (cin >> H >> W) {
        vector<string> grid(H);
        for (int i = 0; i < H; i++) cin >> grid[i];

        int F = 0; // number of floor tiles (s counts as floor)
        vector<pair<int,int>> floors;

        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                if (grid[i][j] == '.' || grid[i][j] == 's')
                    floors.push_back({i, j}), F++;

        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};

        double S = 0;
        vector<vector<double>> dist(H, vector<double>(W, 1e18));

        for (int iter = 0; iter < 300; iter++) {
            // Dijkstra
            priority_queue<tuple<double,int,int>, vector<tuple<double,int,int>>, greater<>> pq;
            fill(dist.begin(), dist.end(), vector<double>(W, 1e18));
            for (int i = 0; i < H; i++)
                for (int j = 0; j < W; j++)
                    if (grid[i][j] == 'g') { dist[i][j] = 0; pq.push({0,i,j}); }

            while (!pq.empty()) {
                auto [d, x, y] = pq.top(); pq.pop();
                if (d > dist[x][y] + 1e-9) continue;
                for (int k = 0; k < 4; k++) {
                    int nx = x+dx[k], ny = y+dy[k];
                    if (nx<0||nx>=H||ny<0||ny>=W||grid[nx][ny]=='#') continue;
                    double nd = d + 1;
                    if (grid[nx][ny] == '*') nd = d + 1 + S; // stepping on spring costs 1 + S
                    // Wait, spring teleports to floor, so cost is 1 (to reach spring) + S (expected from floor)
                    if (nd < dist[nx][ny]) { dist[nx][ny] = nd; pq.push({nd,nx,ny}); }
                }
            }
            double newS = 0;
            for (auto [fx, fy] : floors) newS += dist[fx][fy];
            newS /= F;
            S = newS;
        }

        // find start
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                if (grid[i][j] == 's') { printf("%.6f\n", dist[i][j]); return 0; }
    }
}

