using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> grid(H);
    int start_r = -1, start_c = -1;
    int floor_count = 0;
    // We'll map each floor cell to an index
    vector<pair<int,int>> floor_cells;
    vector<vector<int>> floor_id(H, vector<int>(W, -1));

    for (int i = 0; i < H; i++) {
        cin >> grid[i];
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 's') {
                start_r = i; start_c = j;
                // start is also a floor
                floor_id[i][j] = floor_cells.size();
                floor_cells.push_back({i,j});
                floor_count++;
            } else if (grid[i][j] == '.') {
                floor_id[i][j] = floor_cells.size();
                floor_cells.push_back({i,j});
                floor_count++;
            } else if (grid[i][j] == 'g') {
                // goal not counted as floor for teleportation, but we treat separately.
                // We still assign an ID for convenience in DP? Actually goal is absorbing.
                // We'll treat goal as having expected value 0.
                floor_id[i][j] = -2; // special marker
            } else if (grid[i][j] == '*') {
                // spring: not a floor
            }
            // '#' walls ignored
        }
    }

    int N = floor_cells.size(); // number of floor tiles (excluding goal and spring)
    vector<vector<int>> adj(N);
    vector<int> out_deg(N, 0);
    vector<bool> is_spring(N, false);
    // Also store for each floor tile if it has a spring neighbor? Actually we need to handle springs.
    // We'll do BFS/DP on state = floor tile index.
    // But from a floor tile, moving to a spring triggers teleport.
    // We'll precompute for each floor tile the possible next states and probabilities.

    // Directions
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    // For each floor cell, we need to compute the expected value.
    // We'll set up linear equations: E[i] = 1 + sum_{move} (1/out_deg[i]) * E[next]
    // where next is:
    //   - if neighbor is goal: 0
    //   - if neighbor is floor: E[neighbor]
    //   - if neighbor is spring: average over all floor cells (excluding goal and spring) of E[floor]
    // Note: if a move leads to a spring, the move itself counts as 1 move, then teleport happens instantly (no extra move count).
    // So from floor i, each neighbor direction that is not wall:
    //   cost = 1 (the move) plus expected value after landing.
    // So equation: E[i] = (1/deg) * sum_{dir} (1 + E_after_move)
    // = 1 + (1/deg) * sum_{dir} E_after_move
    // where E_after_move is:
    //   if goal: 0
    //   if floor: E[neighbor]
    //   if spring: avg_floor_E

    // Let avg_floor_E = (1/N) * sum_{j in floors} E[j]
    // But note: if spring sends to any floor uniformly, including possibly the same floor? "any floor tile (excluding stairs and spring tiles)". So yes, uniform over all floor cells (including start and all '.').
    // So avg = (1/N) * sum_{j=0}^{N-1} E[j]

    // Now we have N unknowns E[0..N-1] and one extra unknown avg, but avg is linear combination.
    // So we can set up N equations.

    // First, for each floor cell, compute its degree and list of contributions.
    vector<vector<double>> A(N, vector<double>(N+1, 0.0)); // augmented matrix

    double invN = 1.0 / N;

    for (int idx = 0; idx < N; idx++) {
        int r = floor_cells[idx].first;
        int c = floor_cells[idx].second;
        int deg = 0;
        vector<int> floor_targets;
        int spring_count = 0;
        int goal_count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            char ch = grid[nr][nc];
            if (ch == '#') continue;
            deg++;
            if (ch == 'g') {
                goal_count++;
            } else if (ch == '.' || ch == 's') {
                int nid = floor_id[nr][nc];
                floor_targets.push_back(nid);
            } else if (ch == '*') {
                spring_count++;
            }
        }
        // Equation: E[idx] = 1 + (1/deg) * (goal_count*0 + sum_{floor} E[nid] + spring_count * avg)
        // => E[idx] - (1/deg)*sum_{floor} E[nid] - (spring_count/deg)*avg = 1
        // avg = (1/N)*sum_{j} E[j]
        // So: E[idx] - (1/deg)*sum_{floor} E[nid] - (spring_count/deg)*(1/N)*sum_{j} E[j] = 1
        // => E[idx] - (1/deg)*sum_{floor} E[nid] - (spring_count/(deg*N))*sum_{j} E[j] = 1
        // Rearranged: coefficient for E[idx] is 1 - (spring_count/(deg*N))
        // For other j: coefficient = - (1/deg if j in floor_targets) - (spring_count/(deg*N))
        // Let's build row.
        for (int j = 0; j < N; j++) {
            double coeff = 0.0;
            // contribution from spring average
            coeff -= (double)spring_count / (deg * N);
            // contribution from direct floor neighbor
            // We'll add later for specific j
            A[idx][j] = coeff;
        }
        // Now add the direct neighbor contributions
        for (int nid : floor_targets) {
            A[idx][nid] -= 1.0 / deg; // because it's subtracted in equation
        }
        // Add the coefficient for E[idx] itself: 1
        A[idx][idx] += 1.0;
        // RHS = 1
        A[idx][N] = 1.0;
    }

    // Gaussian elimination
    for (int i = 0; i < N; i++) {
        // Find pivot
        int pivot = i;
        while (pivot < N && fabs(A[pivot][i]) < 1e-12) pivot++;
        if (pivot == N) continue; // shouldn't happen
        swap(A[i], A[pivot]);
        double piv_val = A[i][i];
        for (int j = i; j <= N; j++) {
            A[i][j] /= piv_val;
        }
        for (int k = 0; k < N; k++) {
            if (k == i) continue;
            double factor = A[k][i];
            for (int j = i; j <= N; j++) {
                A[k][j] -= factor * A[i][j];
            }
        }
    }

    // Extract answer
    int start_id = floor_id[start_r][start_c];
    double ans = A[start_id][N];
    cout << fixed << setprecision(10) << ans << "\n";

    return 0;
}

