            }
            ndp[v] = best;
            diff = max(diff, fabs(ndp[v] - dp[v]));
        }
        dp.swap(ndp);
        if (diff < 1e-12) break;
    }

    cout << fixed << setprecision(15) << dp[start] << "\n";
    return 0;
