import java.util.*;

public class SpringTiles {
    static int H, W;
    static char[][] grid;
    static int[][] id;
    static List<Integer> floorCells = new ArrayList<>();
    static int startId, goalId;
    static int N;
    static double[] dp;
    static boolean[] visited;
    static boolean[] isSpring;
    static int[] floorIndex;
    static List<Integer>[] graph;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        sc.nextLine();
        grid = new char[H][W];
        id = new int[H][W];
        for (int i = 0; i < H; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Assign ids to walkable tiles (floor, start, goal, springs)
        N = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] != '#') {
                    id[i][j] = N++;
                    if (grid[i][j] == 's') startId = N - 1;
                    if (grid[i][j] == 'g') goalId = N - 1;
                } else {
                    id[i][j] = -1;
                }
            }
        }

        floorCells.clear();
        isSpring = new boolean[N];
        floorIndex = new int[N];
        Arrays.fill(floorIndex, -1);
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] != '#') {
                    if (grid[i][j] == '*') {
                        isSpring[id[i][j]] = true;
                    } else {
                        floorIndex[id[i][j]] = floorCells.size();
                        floorCells.add(id[i][j]);
                    }
                }
            }
        }

        // Build graph of normal moves
        graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == '#') continue;
                int u = id[i][j];
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d];
                    int nj = j + dy[d];
                    if (ni >= 0 && ni < H && nj >= 0 && nj < W && grid[ni][nj] != '#') {
                        graph[u].add(id[ni][nj]);
                    }
                }
            }
        }

        dp = new double[N];
        visited = new boolean[N];
        Arrays.fill(dp, -1);
        double ans = solve(startId);
        System.out.printf("%.10f%n", ans);
    }

    static double solve(int u) {
        if (u == goalId) return 0;
        if (visited[u]) return dp[u];
        visited[u] = true;

        if (isSpring[u]) {
            // Spring: expected moves = 1 + average of all floor tiles
            double sum = 0;
            for (int f : floorCells) {
                sum += solve(f);
            }
            dp[u] = 1 + sum / floorCells.size();
        } else {
            // Floor tile: need to compute optimal choice
            // We can either move to a neighbor or stay? Actually "best strategy" means we can choose
            // which neighbor to move to. Since we want to minimize expected steps,
            // we should pick the neighbor with minimal expected value.
            double best = Double.POSITIVE_INFINITY;
            for (int v : graph[u]) {
                double val = 1 + solve(v);
                if (val < best) best = val;
            }
            dp[u] = best;
        }
        return dp[u];
    }
}

