public class Main {
    static final double INF = 1e100;
    static final double EPS = 1e-12;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] grid = new char[H][];
        for (int i = 0; i < H; i++) {
            String s = fs.next();
            grid[i] = s.toCharArray();
        }

        int[][] id = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(id[i], -1);

        int n = 0;
        int start = -1;
        List<int[]> cells = new ArrayList<>();

        // States are all non-wall, non-stairs tiles:
        // floor '.', start 's', spring '*'
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                char c = grid[i][j];
                if (c != '#' && c != 'g') {
                    id[i][j] = n++;
                    cells.add(new int[]{i, j});
                }
            }
        }

        boolean[] isSpring = new boolean[n];
        boolean[] isFloor = new boolean[n]; // '.' or 's'
        for (int v = 0; v < n; v++) {
            int x = cells.get(v)[0], y = cells.get(v)[1];
            char c = grid[x][y];
            if (c == '*') isSpring[v] = true;
            if (c == '.' || c == 's') isFloor[v] = true;
            if (c == 's') start = v;
        }

        int floorCount = 0;
        for (boolean b : isFloor) if (b) floorCount++;

        // If there is no floor tile to land on from a spring, then any spring is a dead end.
        // The general equations below still work if floorCount == 0, by treating spring expectation as INF.
        List<Integer>[] moves = new ArrayList[n];
        boolean[] canExitDirect = new boolean[n];

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int v = 0; v < n; v++) {
            moves[v] = new ArrayList<>();
            int x = cells.get(v)[0], y = cells.get(v)[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                char c = grid[nx][ny];
                if (c == '#') continue;
                if (c == 'g') {
                    canExitDirect[v] = true;
                } else {
                    moves[v].add(id[nx][ny]);
                }
            }
        }

        // Value iteration on Bellman equations.
        // Let E[v] be optimal expected moves to escape from state v.
        // For spring tile:
        //   E[v] = 1 + A, where A = average E[floor states], if floorCount > 0; else INF
        // For floor/start tile:
        //   E[v] = 1 + min( 0 if adjacent to g, E[next] for each adjacent non-wall non-g tile )
        //
        // Since spring destinations depend on average over floor states, we iterate to fixed point.
        double[] cur = new double[n];
        double[] nxt = new double[n];

        Arrays.fill(cur, 0.0);

        for (int iter = 0; iter < 200000; iter++) {
            double avgFloor;
            if (floorCount == 0) {
                avgFloor = INF;
            } else {
                double sum = 0.0;
                for (int v = 0; v < n; v++) {
                    if (isFloor[v]) sum += cur[v];
                }
                avgFloor = sum / floorCount;
            }

            double maxDiff = 0.0;

            for (int v = 0; v < n; v++) {
                double val;
                if (isSpring[v]) {
                    if (avgFloor >= INF / 2) val = INF;
                    else val = 1.0 + avgFloor;
                } else {
                    double best = canExitDirect[v] ? 0.0 : INF;
                    for (int to : moves[v]) {
                        if (cur[to] < best) best = cur[to];
                    }
                    if (best >= INF / 2) val = INF;
                    else val = 1.0 + best;
                }
                nxt[v] = val;
                double diff = Math.abs(nxt[v] - cur[v]);
                if (diff > maxDiff) maxDiff = diff;
            }

            double[] tmp = cur;
            cur = nxt;
            nxt = tmp;

            if (maxDiff < 1e-11) break;
        }

        double ans = cur[start];

        // The problem guarantees/assumes an answer exists; if unreachable, this would be huge.
        // Print with sufficient precision.
        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

